# hypothesis: a function with a positional-only parameter and a keyword-only default satisfies a callback protocol, while a function without that keyword-only parameter is rejected statically and raises TypeError at runtime.
from collections.abc import Callable
from typing import Protocol, assert_type, reveal_type


class Scorer(Protocol):
    def __call__(self, value: int, /, *, weight: int = 1) -> int: ...


def apply_weighted(fn: Scorer, v: int) -> int:
    return fn(v, weight=2)


def double(value: int, /, *, weight: int = 1) -> int:
    return value * 2 * weight


def plain(value: int, /) -> int:
    return value + 100


def make_adder(n: int) -> Callable[[int], int]:
    return lambda x: x + n


print(apply_weighted(double, 3))
reveal_type(double)
add5 = make_adder(5)
reveal_type(add5)
assert_type(add5(1), int)
print(add5(10), apply_weighted(lambda v, weight=1: v * weight, 4))


def bad_call(f: Scorer) -> int:
    return f(1, weight=3)


try:
    bad_call(plain)  # expect-error: plain has no keyword-only weight
except TypeError as exc:
    print('runtime:', type(exc).__name__)
